"""Inspect the current workspace for existing SQLite databases and project files."""

import os
import sqlite3
import sys

ROOT = os.getcwd()

print(f"Working directory: {ROOT}\n")

entries = sorted(os.listdir(ROOT))
print("Directory contents:")
for entry in entries:
    full = os.path.join(ROOT, entry)
    kind = "dir" if os.path.isdir(full) else "file"
    size = os.path.getsize(full) if os.path.isfile(full) else "-"
    print(f"  [{kind:4}] {entry}  ({size} bytes)")

# Look for SQLite database files by extension or SQLite header magic.
db_files = []
for entry in entries:
    full = os.path.join(ROOT, entry)
    if os.path.isfile(full):
        lower = entry.lower()
        if lower.endswith((".db", ".sqlite", ".sqlite3", ".db3")):
            db_files.append(full)
        else:
            try:
                with open(full, "rb") as fh:
                    header = fh.read(16)
                if header.startswith(b"SQLite format 3\x00"):
                    db_files.append(full)
            except OSError:
                pass

if not db_files:
    print("\nNo existing SQLite database found in this folder.")
    sys.exit(0)

for path in db_files:
    print(f"\n=== Database: {path} ===")
    try:
        with sqlite3.connect(path) as conn:
            cur = conn.cursor()
            tables = cur.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
            if not tables:
                print("  (no tables)")
            for (table,) in tables:
                print(f"  table: {table}")
                for row in cur.execute(f"PRAGMA table_info('{table}')"):
                    print(f"    - column: {row[1]} (type={row[2]}, notnull={row[3]}, pk={row[5]})")
                count = cur.execute(f"SELECT COUNT(*) FROM '{table}'").fetchone()[0]
                print(f"    rows: {count}")
    except sqlite3.Error as exc:
        print(f"  error reading database: {exc}")

